def unique_digits(x):
    # Validate input
    if not all(isinstance(num, int) and num > 0 for num in x):
        raise ValueError("Input list should only contain positive integers.")

    # Filter out elements with even digits
    def has_even_digit(num):
        return any(int(digit) % 2 == 0 for digit in str(num))

    filtered_list = [num for num in x if not has_even_digit(num)]

    # Sort the remaining elements
    sorted_list = sorted(filtered_list)

    return sorted_list
